window.docContents[45].resolve({"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Section-6___8-heading-and-setup-for-proof-of-Gabriel___s-theorem/#Chapter6___Section6___8_heading":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.8. Proof of Gabriel's theorem\tSection 6.8 heading and setup for proof of Gabriel's theorem","header":"Section 6.8 heading and setup for proof of Gabriel's theorem","id":"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Section-6___8-heading-and-setup-for-proof-of-Gabriel___s-theorem/#Chapter6___Section6___8_heading"},"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/Section-2___7___-Examples-of-algebras-___-Weyl-algebra-and-q-Weyl-algebra/#Chapter2___Discussion_2___7_intro___heading-1":{"contents":"The following two examples are among the simplest interesting examples of noncommutative associative algebras:\n\n(1) the Weyl algebra, k\\langle x, y \\rangle / \\langle yx - xy - 1 \\rangle;\n\n(2) the q-Weyl algebra, generated by x, x^{-1}, y, y^{-1} with defining relations yx = qxy and xx^{-1} = x^{-1}x = yy^{-1} = y^{-1}y = 1.\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.7. Examples of algebras\tSection 2.7: Examples of algebras — Weyl algebra and q-Weyl algebra","header":"2.7. Examples of algebras","id":"/2___-Basic-notions-of-representation-theory/2___7___-Examples-of-algebras/Section-2___7___-Examples-of-algebras-___-Weyl-algebra-and-q-Weyl-algebra/#Chapter2___Discussion_2___7_intro___heading-1"}});
